-- 0003_taskers.sql
-- Tasker applications, public profiles, specialties, service areas, portfolio,
-- and the payout-token boundary (no raw wallet/card credentials).

create table if not exists public.tasker_applications (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references public.profiles(id) on delete cascade,
  status           tasker_application_status not null default 'DRAFT',
  bio              text not null check (char_length(bio) between 20 and 2000),
  experience       text not null check (char_length(experience) between 1 and 2000),
  payout_provider  text,
  -- Payout token boundary: only an opaque reference, never raw credentials.
  payout_reference text,
  submitted_at     timestamptz,
  decided_at       timestamptz,
  decided_by       uuid references public.profiles(id),
  decision_reason  text,
  version          integer not null default 1 check (version >= 1),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint chk_no_raw_card check (payout_reference is null or payout_reference !~ '^[0-9]{13,19}$')
);

create unique index if not exists uq_tasker_application_active
  on public.tasker_applications (user_id)
  where status in ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'RESUBMISSION_REQUIRED');

drop trigger if exists trg_tasker_applications_updated_at on public.tasker_applications;
create trigger trg_tasker_applications_updated_at
  before update on public.tasker_applications
  for each row execute function app.set_updated_at();

-- Public trust profile. Excludes private identity/payout/exact address/admin notes.
create table if not exists public.tasker_profiles (
  user_id          uuid primary key references public.profiles(id) on delete cascade,
  public_bio       text not null default '',
  public_experience text not null default '',
  completion_count integer not null default 0 check (completion_count >= 0),
  rating_sum       integer not null default 0 check (rating_sum >= 0),
  rating_count     integer not null default 0 check (rating_count >= 0),
  approved_at      timestamptz,
  suspended_at     timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

drop trigger if exists trg_tasker_profiles_updated_at on public.tasker_profiles;
create trigger trg_tasker_profiles_updated_at
  before update on public.tasker_profiles
  for each row execute function app.set_updated_at();

create table if not exists public.specialties (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique,
  name       text not null,
  active     boolean not null default true,
  sort_order integer not null default 0
);

create table if not exists public.tasker_specialties (
  user_id      uuid not null references public.profiles(id) on delete cascade,
  specialty_id uuid not null references public.specialties(id) on delete cascade,
  primary key (user_id, specialty_id)
);

create table if not exists public.service_areas (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles(id) on delete cascade,
  city_code     text not null,
  barangay_code text,
  radius_km     integer check (radius_km is null or (radius_km between 1 and 100)),
  created_at    timestamptz not null default now()
);

create index if not exists ix_service_areas_user on public.service_areas (user_id);
create index if not exists ix_service_areas_city on public.service_areas (city_code);

create table if not exists public.portfolio_items (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references public.profiles(id) on delete cascade,
  storage_path     text not null,
  caption          text check (caption is null or char_length(caption) <= 280),
  sort_order       integer not null default 0,
  moderation_status moderation_status not null default 'PENDING',
  created_at       timestamptz not null default now()
);

create index if not exists ix_portfolio_items_user on public.portfolio_items (user_id);

-- payout_methods: masked label + provider reference only; no raw credential.
create table if not exists public.payout_methods (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references public.profiles(id) on delete cascade,
  provider          text not null,
  provider_reference text not null,
  masked_label      text not null,
  status            text not null default 'active' check (status in ('active', 'disabled')),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint chk_payout_no_raw_card check (provider_reference !~ '^[0-9]{13,19}$')
);

drop trigger if exists trg_payout_methods_updated_at on public.payout_methods;
create trigger trg_payout_methods_updated_at
  before update on public.payout_methods
  for each row execute function app.set_updated_at();


-- ===================================================================
-- 0004_marketplace_tasks.sql
-- ===================================================================

-- 0004_marketplace_tasks.sql
-- Categories, tasks, separated public/private locations, media, questions,
-- offers, bookings, and the one-active-booking constraint.

create table if not exists public.categories (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique,
  name       text not null,
  active     boolean not null default true,
  sort_order integer not null default 0
);

create table if not exists public.tasks (
  id              uuid primary key default gen_random_uuid(),
  client_id       uuid not null references public.profiles(id) on delete cascade,
  category_id     uuid not null references public.categories(id),
  title           text not null check (char_length(title) between 5 and 120),
  description     text not null check (char_length(description) between 20 and 4000),
  budget_centavos bigint not null check (budget_centavos >= 2000 and budget_centavos <= 100000000),
  currency        text not null default 'PHP' check (currency = 'PHP'),
  scheduled_for   timestamptz,
  same_day        boolean not null default false,
  status          task_status not null default 'DRAFT',
  published_at    timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create index if not exists ix_tasks_status on public.tasks (status);
create index if not exists ix_tasks_client on public.tasks (client_id);
create index if not exists ix_tasks_category on public.tasks (category_id);
-- Feed access pattern: open tasks newest-first.
create index if not exists ix_tasks_open_published
  on public.tasks (published_at desc)
  where status = 'OPEN';

drop trigger if exists trg_tasks_updated_at on public.tasks;
create trigger trg_tasks_updated_at
  before update on public.tasks
  for each row execute function app.set_updated_at();

-- Public approximate location. Structurally separate from the exact address.
create table if not exists public.task_public_locations (
  task_id         uuid primary key references public.tasks(id) on delete cascade,
  city_code       text not null,
  barangay_code   text not null,
  landmark        text not null default '',
  approximate_point geography(Point, 4326) not null
);

create index if not exists ix_task_public_locations_city
  on public.task_public_locations (city_code, barangay_code);
create index if not exists ix_task_public_locations_geo
  on public.task_public_locations using gist (approximate_point);

-- Private exact location. Never included in any public projection/view.
create table if not exists public.task_private_locations (
  task_id       uuid primary key references public.tasks(id) on delete cascade,
  exact_address text not null,
  exact_point   geography(Point, 4326) not null,
  created_at    timestamptz not null default now()
);

create table if not exists public.task_media (
  id               uuid primary key default gen_random_uuid(),
  task_id          uuid not null references public.tasks(id) on delete cascade,
  storage_path     text not null,
  kind             text not null check (kind in ('image', 'video')),
  moderation_status moderation_status not null default 'PENDING',
  sort_order       integer not null default 0,
  created_at       timestamptz not null default now()
);

create index if not exists ix_task_media_task on public.task_media (task_id);

create table if not exists public.task_questions (
  id         uuid primary key default gen_random_uuid(),
  task_id    uuid not null references public.tasks(id) on delete cascade,
  author_id  uuid not null references public.profiles(id) on delete cascade,
  body       text not null check (char_length(body) between 1 and 1000),
  status     moderation_status not null default 'APPROVED',
  answer     text,
  answered_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists ix_task_questions_task on public.task_questions (task_id);

create table if not exists public.offers (
  id               uuid primary key default gen_random_uuid(),
  task_id          uuid not null references public.tasks(id) on delete cascade,
  tasker_id        uuid not null references public.profiles(id) on delete cascade,
  amount_centavos  bigint not null check (amount_centavos > 0 and amount_centavos <= 100000000),
  currency         text not null default 'PHP' check (currency = 'PHP'),
  message          text not null check (char_length(message) between 1 and 2000),
  eta_text         text not null,
  availability_text text not null,
  experience_text  text not null,
  status           offer_status not null default 'SUBMITTED',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  -- A Tasker may have at most one active offer per task.
  constraint uq_offer_task_tasker unique (task_id, tasker_id)
);

create index if not exists ix_offers_task on public.offers (task_id);
create index if not exists ix_offers_tasker on public.offers (tasker_id);

drop trigger if exists trg_offers_updated_at on public.offers;
create trigger trg_offers_updated_at
  before update on public.offers
  for each row execute function app.set_updated_at();

create table if not exists public.bookings (
  id               uuid primary key default gen_random_uuid(),
  task_id          uuid not null references public.tasks(id) on delete cascade,
  accepted_offer_id uuid not null references public.offers(id),
  client_id        uuid not null references public.profiles(id),
  tasker_id        uuid not null references public.profiles(id),
  agreed_centavos  bigint not null check (agreed_centavos > 0 and agreed_centavos <= 100000000),
  currency         text not null default 'PHP' check (currency = 'PHP'),
  status           booking_status not null default 'PAYMENT_PENDING',
  idempotency_key  text not null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint uq_booking_accepted_offer unique (accepted_offer_id),
  constraint uq_booking_idempotency unique (idempotency_key),
  constraint chk_booking_participants check (client_id <> tasker_id)
);

-- One-active-booking-per-task invariant (core invariant 3).
create unique index if not exists uq_booking_active_per_task
  on public.bookings (task_id)
  where status in ('PAYMENT_PENDING', 'CONFIRMED', 'IN_PROGRESS', 'COMPLETION_REQUESTED');

create index if not exists ix_bookings_client on public.bookings (client_id);
create index if not exists ix_bookings_tasker on public.bookings (tasker_id);

drop trigger if exists trg_bookings_updated_at on public.bookings;
create trigger trg_bookings_updated_at
  before update on public.bookings
  for each row execute function app.set_updated_at();

create table if not exists public.booking_events (
  id             uuid primary key default gen_random_uuid(),
  booking_id     uuid not null references public.bookings(id) on delete cascade,
  from_status    booking_status,
  to_status      booking_status not null,
  actor_id       uuid references public.profiles(id),
  source         text not null default 'system' check (source in ('client', 'tasker', 'admin', 'provider', 'system')),
  idempotency_key text,
  metadata       jsonb not null default '{}'::jsonb,
  created_at     timestamptz not null default now(),
  constraint uq_booking_event_idempotency unique (booking_id, idempotency_key)
);

create index if not exists ix_booking_events_booking on public.booking_events (booking_id, created_at);

create table if not exists public.offer_events (
  id         uuid primary key default gen_random_uuid(),
  offer_id   uuid not null references public.offers(id) on delete cascade,
  actor_id   uuid references public.profiles(id),
  event_type text not null,
  metadata   jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists ix_offer_events_offer on public.offer_events (offer_id, created_at);


-- ===================================================================
-- 0005_messaging_notifications.sql
-- ===================================================================

-- 0005_messaging_notifications.sql
-- Conversations tied to confirmed bookings, messages, media, and notifications.

create table if not exists public.conversations (
  id         uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint uq_conversation_booking unique (booking_id)
);

create table if not exists public.conversation_participants (
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  user_id         uuid not null references public.profiles(id) on delete cascade,
  created_at      timestamptz not null default now(),
  primary key (conversation_id, user_id)
);

create index if not exists ix_conversation_participants_user
  on public.conversation_participants (user_id);

create table if not exists public.messages (
  id               uuid primary key default gen_random_uuid(),
  conversation_id  uuid not null references public.conversations(id) on delete cascade,
  sender_id        uuid not null references public.profiles(id),
  body             text check (body is null or char_length(body) <= 4000),
  moderation_status moderation_status not null default 'APPROVED',
  created_at       timestamptz not null default now(),
  edited_at        timestamptz
);

create index if not exists ix_messages_conversation on public.messages (conversation_id, created_at);

create table if not exists public.message_media (
  id          uuid primary key default gen_random_uuid(),
  message_id  uuid not null references public.messages(id) on delete cascade,
  storage_path text not null,
  kind        text not null check (kind in ('image', 'video')),
  mime_type   text not null,
  size_bytes  bigint not null check (size_bytes > 0 and size_bytes <= 104857600),
  created_at  timestamptz not null default now()
);

create index if not exists ix_message_media_message on public.message_media (message_id);

create table if not exists public.notifications (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles(id) on delete cascade,
  type           text not null,
  title          text not null,
  body           text not null,
  resource_type  text,
  resource_id    uuid,
  read_at        timestamptz,
  delivery_status notification_delivery_status not null default 'PENDING',
  created_at     timestamptz not null default now()
);

create index if not exists ix_notifications_user on public.notifications (user_id, created_at desc);
create index if not exists ix_notifications_unread
  on public.notifications (user_id)
  where read_at is null;

create table if not exists public.notification_preferences (
  user_id  uuid not null references public.profiles(id) on delete cascade,
  category text not null check (category in
    ('verification', 'offers', 'bookings', 'payments', 'messages', 'disputes', 'system')),
  in_app   boolean not null default true,
  push     boolean not null default true,
  primary key (user_id, category)
);


-- ===================================================================
-- 0006_finance_ledger.sql
-- ===================================================================

-- 0006_finance_ledger.sql
-- Payment intents, provider event inbox, append-only balanced ledger, refunds,
-- and withdrawals. No mutable authoritative balance column exists; balances are
-- always derived from immutable ledger entries.

create table if not exists public.payment_intents (
  id                uuid primary key default gen_random_uuid(),
  booking_id        uuid not null references public.bookings(id) on delete cascade,
  provider          text not null,
  provider_reference text,
  amount_centavos   bigint not null check (amount_centavos > 0),
  currency          text not null default 'PHP' check (currency = 'PHP'),
  status            payment_status not null default 'CREATED',
  idempotency_key   text not null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint uq_payment_intent_idempotency unique (idempotency_key),
  constraint uq_payment_intent_provider_reference unique (provider, provider_reference)
);

create index if not exists ix_payment_intents_booking on public.payment_intents (booking_id);

drop trigger if exists trg_payment_intents_updated_at on public.payment_intents;
create trigger trg_payment_intents_updated_at
  before update on public.payment_intents
  for each row execute function app.set_updated_at();

-- Provider event inbox for signed webhook events. Payload is restricted; only
-- a hash and safe fields are retained. External event id is unique for replay
-- protection.
create table if not exists public.provider_events (
  id                uuid primary key default gen_random_uuid(),
  provider          text not null,
  external_event_id text not null,
  event_type        text not null,
  provider_reference text,
  amount_centavos   bigint,
  currency          text,
  signature_valid   boolean not null,
  payload_hash      text not null,
  processing_status provider_event_status not null default 'RECEIVED',
  error_code        text,
  received_at       timestamptz not null default now(),
  processed_at      timestamptz,
  constraint uq_provider_event unique (provider, external_event_id)
);

create index if not exists ix_provider_events_status on public.provider_events (processing_status);

-- Ledger accounts. Platform accounts have null owner_id; user accounts set it.
create table if not exists public.ledger_accounts (
  id           uuid primary key default gen_random_uuid(),
  owner_type   text not null check (owner_type in ('platform', 'client', 'tasker')),
  owner_id     uuid references public.profiles(id) on delete restrict,
  account_type ledger_account_type not null,
  currency     text not null default 'PHP' check (currency = 'PHP'),
  created_at   timestamptz not null default now(),
  constraint uq_ledger_account unique (owner_type, owner_id, account_type, currency)
);

create index if not exists ix_ledger_accounts_owner on public.ledger_accounts (owner_id);

create table if not exists public.ledger_transactions (
  id                uuid primary key default gen_random_uuid(),
  booking_id        uuid references public.bookings(id) on delete restrict,
  type              ledger_transaction_type not null,
  idempotency_key   text not null,
  provider_event_id uuid references public.provider_events(id),
  created_by        uuid references public.profiles(id),
  metadata          jsonb not null default '{}'::jsonb,
  created_at        timestamptz not null default now(),
  constraint uq_ledger_transaction_idempotency unique (idempotency_key)
);

create index if not exists ix_ledger_transactions_booking on public.ledger_transactions (booking_id);

create table if not exists public.ledger_entries (
  id             uuid primary key default gen_random_uuid(),
  transaction_id uuid not null references public.ledger_transactions(id) on delete restrict,
  account_id     uuid not null references public.ledger_accounts(id) on delete restrict,
  amount_centavos bigint not null check (amount_centavos <> 0),
  created_at     timestamptz not null default now()
);

create index if not exists ix_ledger_entries_transaction on public.ledger_entries (transaction_id);
create index if not exists ix_ledger_entries_account on public.ledger_entries (account_id);

-- ---------------------------------------------------------------------------
-- Immutability: ledger transactions and entries are append-only.
-- ---------------------------------------------------------------------------
create or replace function app.forbid_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception 'Ledger rows are append-only and cannot be % (immutable).', tg_op
    using errcode = 'restrict_violation';
end;
$$;

drop trigger if exists trg_ledger_entries_immutable on public.ledger_entries;
create trigger trg_ledger_entries_immutable
  before update or delete on public.ledger_entries
  for each row execute function app.forbid_mutation();

drop trigger if exists trg_ledger_transactions_immutable on public.ledger_transactions;
create trigger trg_ledger_transactions_immutable
  before update or delete on public.ledger_transactions
  for each row execute function app.forbid_mutation();

-- ---------------------------------------------------------------------------
-- Balanced-to-zero enforcement via a DEFERRED constraint trigger. Checked at
-- commit so multi-entry inserts within a transaction can complete first.
-- ---------------------------------------------------------------------------
create or replace function app.assert_transaction_balanced()
returns trigger
language plpgsql
as $$
declare
  v_sum bigint;
  v_count integer;
begin
  select coalesce(sum(amount_centavos), 0), count(*)
    into v_sum, v_count
  from public.ledger_entries
  where transaction_id = new.transaction_id;

  if v_count < 2 then
    raise exception 'Ledger transaction % must have at least two entries.', new.transaction_id
      using errcode = 'check_violation';
  end if;

  if v_sum <> 0 then
    raise exception 'Ledger transaction % is not balanced (sum=%).', new.transaction_id, v_sum
      using errcode = 'check_violation';
  end if;

  return null;
end;
$$;

drop trigger if exists trg_ledger_entries_balanced on public.ledger_entries;
create constraint trigger trg_ledger_entries_balanced
  after insert on public.ledger_entries
  deferrable initially deferred
  for each row execute function app.assert_transaction_balanced();

-- ---------------------------------------------------------------------------
-- Refunds and withdrawals
-- ---------------------------------------------------------------------------
create table if not exists public.refunds (
  id                uuid primary key default gen_random_uuid(),
  payment_intent_id uuid not null references public.payment_intents(id) on delete restrict,
  amount_centavos   bigint not null check (amount_centavos > 0),
  status            refund_status not null default 'REQUESTED',
  reason            text,
  provider_reference text,
  idempotency_key   text not null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint uq_refund_idempotency unique (idempotency_key)
);

drop trigger if exists trg_refunds_updated_at on public.refunds;
create trigger trg_refunds_updated_at
  before update on public.refunds
  for each row execute function app.set_updated_at();

create table if not exists public.withdrawals (
  id                uuid primary key default gen_random_uuid(),
  tasker_id         uuid not null references public.profiles(id) on delete restrict,
  payout_method_id  uuid not null references public.payout_methods(id) on delete restrict,
  amount_centavos   bigint not null check (amount_centavos > 0),
  status            withdrawal_status not null default 'REQUESTED',
  provider_reference text,
  idempotency_key   text not null,
  failure_reason    text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint uq_withdrawal_idempotency unique (idempotency_key)
);

create index if not exists ix_withdrawals_tasker on public.withdrawals (tasker_id, created_at desc);

drop trigger if exists trg_withdrawals_updated_at on public.withdrawals;
create trigger trg_withdrawals_updated_at
  before update on public.withdrawals
  for each row execute function app.set_updated_at();


