-- Storage signed-URL authorization for a trusted server-side adapter.
-- Given a bucket + object name, binds the object to its real table row and
-- verifies the caller is the assigned Admin for that row (active capability).
-- On success it writes exactly one audit event (idempotent per key) and returns
-- TRUE; on a malformed/unbound path or wrong/unassigned caller it returns FALSE
-- and writes nothing. It NEVER returns object bytes or a URL. Contract: the
-- signed-URL adapter MUST call this with the acting Admin's JWT and may ask the
-- service role to sign a short-lived URL ONLY when it returns TRUE. (Do not log
-- from an RLS predicate — this SECURITY DEFINER function is the audit point.)
create or replace function public.admin_authorize_object_read(
  p_bucket text, p_name text, p_reason text, p_idempotency_key text
)
returns boolean
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_ok boolean := false;
  v_cap user_capability;
  v_rtype text;
  v_rid uuid;
  v_ert text;
  v_erid uuid;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);

  if p_bucket = 'id-documents' then
    select vd.case_id into v_rid from public.verification_documents vd where vd.storage_path = p_name;
    if v_rid is not null and app.admin_assigned_verification(v_rid) then
      v_ok := true; v_rtype := 'verification_case';
    end if;
  elsif p_bucket = 'chat-media' then
    select m.conversation_id into v_rid
      from public.message_media mm join public.messages m on m.id = mm.message_id
      where mm.storage_path = p_name;
    if v_rid is not null and app.admin_assigned_conversation(v_rid) then
      v_ok := true; v_rtype := 'conversation';
    end if;
  elsif p_bucket = 'evidence' then
    select e.resource_type, e.resource_id into v_ert, v_erid
      from public.evidence e where e.storage_path = p_name;
    if v_erid is not null and app.admin_assigned_evidence(v_ert, v_erid) then
      v_ok := true; v_rtype := v_ert; v_rid := v_erid;
    end if;
  elsif p_bucket = 'task-media' then
    select tm.task_id into v_rid from public.task_media tm where tm.storage_path = p_name;
    if v_rid is not null and app.admin_assigned_task(v_rid) then
      v_ok := true; v_rtype := 'task';
    end if;
  end if;

  if not v_ok then
    return false;
  end if;

  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_FINANCE','ADMIN_SUPER']::user_capability[]);
  perform pg_advisory_xact_lock(hashtextextended(
    jsonb_build_array('dizkarte:audit-read', auth.uid(),
                      'admin.storage.authorize', v_rtype, v_rid,
                      p_bucket, p_name, p_idempotency_key)::text,
    0));

  if not exists (
    select 1 from public.audit_logs
    where actor_id = auth.uid() and action = 'admin.storage.authorize'
      and resource_type = v_rtype and resource_id = v_rid
      and safe_metadata->>'bucket' = p_bucket
      and safe_metadata->>'object_name' = p_name
      and safe_metadata->>'idempotency_key' = p_idempotency_key
  ) then
    insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
    values (auth.uid(), 'admin.storage.authorize', v_rtype, v_rid,
            jsonb_build_object('capability', v_cap, 'reason', p_reason,
                               'bucket', p_bucket, 'object_name', p_name,
                               'idempotency_key', p_idempotency_key));
  end if;

  return true;
end;
$$;

-- ===========================================================================
-- SECTION 11 — Execute-grant boundaries for the new RPCs and helpers
-- Public RPCs re-derive auth.uid() and re-check authorization. Revoke default
-- PostgreSQL PUBLIC execution (and any stale explicit grants) before granting
-- only the intended authenticated/service roles. Internal definer helpers are
-- not directly callable, except the narrow predicates required by RLS.
-- ===========================================================================

-- Internal helpers: owner/definer call paths only unless RLS evaluates them.
revoke execute on function app.has_active_capability(user_capability[])
  from public, anon, authenticated, service_role;
revoke execute on function app.is_active_account()
  from public, anon, authenticated, service_role;
revoke execute on function app.safe_uuid(text)
  from public, anon, authenticated, service_role;
revoke execute on function app.storage_seg(text, integer)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_verification(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_report(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_dispute(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_ticket(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_booking(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_conversation(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_task(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_offer(uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.admin_assigned_evidence(text, uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.assert_reasoned(text, text)
  from public, anon, authenticated, service_role;
revoke execute on function app.acting_capability(user_capability[])
  from public, anon, authenticated, service_role;
revoke execute on function app.audit_read_once(text, text, uuid, user_capability, text, text)
  from public, anon, authenticated, service_role;

-- These helpers are direct RLS predicates/path parsers for authenticated rows.
grant execute on function app.has_active_capability(user_capability[]) to authenticated;
grant execute on function app.safe_uuid(text) to authenticated;
grant execute on function app.storage_seg(text, integer) to authenticated;
grant execute on function app.admin_assigned_task(uuid) to authenticated;
grant execute on function app.admin_assigned_offer(uuid) to authenticated;

-- Admin assignment RPCs.
revoke execute on function public.admin_assign_report(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_assign_dispute(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_assign_ticket(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_assign_verification(uuid, text, text)
  from public, anon, authenticated, service_role;

-- Admin transition RPCs.
revoke execute on function public.admin_transition_report(uuid, report_status, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_transition_dispute(uuid, dispute_status, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_transition_ticket(uuid, ticket_status, text, text)
  from public, anon, authenticated, service_role;

-- Audited sensitive-read and storage-authorization RPCs.
revoke execute on function public.admin_read_report_case(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_dispute_case(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_ticket_case(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_ticket_messages(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_conversation_messages(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_conversation_media(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_verification_case(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_evidence(text, uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_read_task_location(uuid, text, text)
  from public, anon, authenticated, service_role;
revoke execute on function public.admin_authorize_object_read(text, text, text, text)
  from public, anon, authenticated, service_role;

grant execute on function public.admin_assign_report(uuid, text, text)              to authenticated;
grant execute on function public.admin_assign_dispute(uuid, text, text)             to authenticated;
grant execute on function public.admin_assign_ticket(uuid, text, text)              to authenticated;
grant execute on function public.admin_assign_verification(uuid, text, text)        to authenticated;

grant execute on function public.admin_transition_report(uuid, report_status, text, text)   to authenticated;
grant execute on function public.admin_transition_dispute(uuid, dispute_status, text, text) to authenticated;
grant execute on function public.admin_transition_ticket(uuid, ticket_status, text, text)   to authenticated;

grant execute on function public.admin_read_report_case(uuid, text, text)            to authenticated;
grant execute on function public.admin_read_dispute_case(uuid, text, text)           to authenticated;
grant execute on function public.admin_read_ticket_case(uuid, text, text)            to authenticated;
grant execute on function public.admin_read_ticket_messages(uuid, text, text)        to authenticated;
grant execute on function public.admin_read_conversation_messages(uuid, text, text)  to authenticated;
grant execute on function public.admin_read_conversation_media(uuid, text, text)     to authenticated;
grant execute on function public.admin_read_verification_case(uuid, text, text)      to authenticated;
grant execute on function public.admin_read_evidence(text, uuid, text, text)         to authenticated;
grant execute on function public.admin_read_task_location(uuid, text, text)          to authenticated;

grant execute on function public.admin_authorize_object_read(text, text, text, text) to authenticated;
grant execute on function public.admin_authorize_object_read(text, text, text, text) to service_role;


-- ===================================================================
-- 0014_api_role_grants.sql
-- ===================================================================

-- 0014_api_role_grants.sql
-- Reconcile PostgreSQL table/sequence privileges for the Supabase API roles.
--
-- WHY THIS EXISTS
-- Row Level Security (enabled on every user-facing table in 0009/0013) is only
-- consulted AFTER a table-level privilege check succeeds. The Supabase API
-- roles (anon, authenticated, service_role) were never granted base-table
-- privileges, so a request running as `authenticated` failed with
-- "permission denied for table ..." BEFORE any RLS policy could run
-- (confirmed: has_table_privilege('authenticated','public.tasks','SELECT') was
-- false). This migration adds the standard Supabase API-role grants so RLS
-- becomes the effective ROW gate. It does NOT widen what any row-level policy
-- already allows — the policies authored in 0009/0013 remain the authorization
-- boundary, and the security_hardening suite's denial assertions are the proof.
--
-- LEAST-PRIVILEGE MODEL
--   * authenticated : SELECT/INSERT/UPDATE/DELETE on all public tables. Every
--       write still requires a matching RLS policy; tables without a write
--       policy stay deny-by-default and are mutated only by SECURITY DEFINER
--       RPCs (which run as the table owner and bypass RLS by design). This
--       preserves the append-only ledger, provider-authoritative refund/payout,
--       one-active-booking, and exact-location/chat gating — none of those
--       tables expose a user-facing write policy.
--   * service_role  : ALL. It has BYPASSRLS and drives the provider finalizers
--       and server-side tooling.
--   * anon          : intentionally NO table/sequence privileges. Every RLS
--       policy in this schema targets the `authenticated` role; there is no
--       `to anon` policy anywhere, so an unauthenticated client has nothing to
--       read or write regardless of grants. Keeping anon at zero base-table
--       access is the least-privilege choice and avoids silently exposing a
--       future non-RLS table to the public.
--
-- NOTE: schema `app` is deliberately NOT added to PostgREST's exposed schemas
-- and receives NO table grants here (it holds only functions). USAGE on schema
-- `app` was already granted in 0001 so RLS predicates can resolve app.* helpers.
-- ===========================================================================

-- --- Existing objects -------------------------------------------------------
-- These target the authored, postgres-owned public tables (all of which have
-- RLS enabled per 0009/0013). The only public table without RLS is PostGIS's
-- public.spatial_ref_sys, which is owned and grant-managed by `supabase_admin`
-- (the Supabase base image), not by the migration role: these statements are a
-- harmless no-op on it and do not change its base-image grants. `authenticated`
-- write access to the authored tables is therefore always gated by RLS.
grant select, insert, update, delete on all tables in schema public to authenticated;
grant all on all tables in schema public to service_role;
grant usage, select on all sequences in schema public to authenticated, service_role;

-- --- Future objects (created by the migration owner) ------------------------
-- Mirror the grants above so later migrations' tables/sequences are covered
-- without a follow-up grant. New tables created by later migrations are still
-- expected to enable RLS (that is the row gate); these defaults only supply the
-- table-level privilege that RLS is checked against.
alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;
alter default privileges in schema public
  grant all on tables to service_role;
alter default privileges in schema public
  grant usage, select on sequences to authenticated, service_role;

-- ===========================================================================
-- Function EXECUTE reconciliation for RLS predicates.
--
-- 0013 SECTION 11 revoked EXECUTE on the app.* helpers from every role, then
-- re-granted only the subset invoked as DIRECT RLS predicates
-- (has_active_capability, safe_uuid, storage_seg, admin_assigned_task,
-- admin_assigned_offer). One direct predicate was missed: the
-- `ticket_messages_insert` WITH CHECK policy (0013 SECTION 2) calls
-- app.admin_assigned_ticket(ticket_id) directly, so the querying role
-- (`authenticated`) must be able to EXECUTE it — otherwise an assigned support
-- Admin's ticket reply fails with "permission denied for function
-- admin_assigned_ticket". Verified against pg_policy: this is the ONLY app.*
-- predicate referenced by any policy (public or storage.objects) that still
-- lacked authenticated EXECUTE.
--
-- All other revoked helpers (admin_assigned_dispute/report/verification/
-- booking/conversation/evidence, acting_capability, assert_reasoned,
-- audit_read_once, is_active_account) are invoked ONLY inside SECURITY DEFINER
-- bodies, which execute as the function owner, so they intentionally remain
-- non-executable by authenticated. The security_hardening suite explicitly
-- asserts admin_assigned_dispute and audit_read_once stay non-executable, which
-- is the safety net proving this grant is not over-broad.
-- ===========================================================================
grant execute on function app.admin_assigned_ticket(uuid) to authenticated;


-- ===================================================================
-- 0015_handle_new_user.sql
-- ===================================================================

-- 0015_handle_new_user.sql
-- Auto-provision an application profile when a Supabase Auth user is created.
--
-- Without this, a real `auth.users` signup has no `public.profiles` row, so
-- every RLS self-read (profile, capabilities, verification, application) would
-- return nothing and the app could not build a session. This trigger closes
-- that gap: it creates the profile and grants the baseline CLIENT capability.
-- Elevated capabilities (TASKER, ADMIN_*) are never granted here — only by an
-- Admin action or the seed script.

create or replace function app.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_display_name text;
begin
  -- Prefer a display name supplied at sign-up; otherwise derive from the email
  -- local part. Clamp to the profiles length constraint (2..80).
  v_display_name := coalesce(
    nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),
    split_part(coalesce(new.email, ''), '@', 1)
  );
  if v_display_name is null or char_length(v_display_name) < 2 then
    v_display_name := 'New User';
  elsif char_length(v_display_name) > 80 then
    v_display_name := left(v_display_name, 80);
  end if;

  insert into public.profiles (id, display_name)
  values (new.id, v_display_name)
  on conflict (id) do nothing;

  -- Baseline capability: anyone can hire (act as a Client). Publishing a paid
  -- task remains gated by identity verification elsewhere.
  insert into public.user_capabilities (user_id, capability)
  values (new.id, 'CLIENT')
  on conflict do nothing;

  return new;
end;
$$;

drop trigger if exists trg_on_auth_user_created on auth.users;
create trigger trg_on_auth_user_created
  after insert on auth.users
  for each row execute function app.handle_new_user();


-- ===================================================================
-- 0016_admin_ops_rpcs.sql
-- ===================================================================

-- 0016_admin_ops_rpcs.sql
-- Admin operations that previously had NO backing surface in the database.
--
-- 0009/0013 deliberately grant Admins a SELECT path to `profiles`, `tasks`, and
-- `categories` but no write path: there is no admin UPDATE/INSERT policy on any
-- of them. That left three Admin console capabilities (account moderation, task
-- moderation, and the service catalog) with nothing real to call.
--
-- Rather than opening broad admin RLS write policies — which cannot record who
-- changed what and why — each operation is a SECURITY DEFINER RPC following the
-- same contract as the 0013 admin commands:
--   * active-capability check via app.acting_capability (deny when null),
--   * bounded non-empty reason + idempotency key via app.assert_reasoned,
--   * row lock, idempotent replay returning the current row without a second
--     audit write,
--   * one immutable moderation_actions row + one audit_logs row per effect.
--
-- Writes still happen as the function owner, so the base tables keep their
-- deny-by-default posture for direct client writes.

-- ---------------------------------------------------------------------------
-- admin_set_account_status (Admin: support/super)
-- Suspend/ban/reinstate an account. Because app.has_active_capability() and
-- app.is_active_account() both require profiles.account_status = 'active', a
-- suspension immediately withdraws every capability-gated surface for that user
-- without touching their capability grants (so reinstatement is lossless).
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_account_status(
  p_user_id uuid,
  p_status account_status,
  p_reason text,
  p_idempotency_key text
)
returns public.profiles
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.profiles;
  v_cap user_capability;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);
  if v_cap is null then
    raise exception 'FORBIDDEN: account moderation requires an active support/super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_status not in ('active','suspended','banned') then
    raise exception 'INVALID_STATE: unsupported account status %', p_status
      using errcode = 'check_violation';
  end if;

  -- An Admin must not lock themselves out of the console.
  if p_user_id = auth.uid() and p_status <> 'active' then
    raise exception 'VALIDATION_ERROR: an Admin cannot suspend or ban their own account.'
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.profiles where id = p_user_id for update;
  if not found then raise exception 'NOT_FOUND: profile' using errcode = 'no_data_found'; end if;

  if v_row.account_status = p_status
     or exists (select 1 from public.moderation_actions ma
                where ma.resource_type = 'user' and ma.resource_id = p_user_id
                  and ma.admin_id = auth.uid()
                  and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  update public.profiles set account_status = p_status, updated_at = now()
    where id = p_user_id returning * into v_row;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), v_cap, 'user', p_user_id, 'account_status:' || p_status, p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'to_status', p_status));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.user.account_status', 'user', p_user_id,
          jsonb_build_object('capability', v_cap, 'to_status', p_status,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

-- ---------------------------------------------------------------------------
-- admin_moderate_task (Admin: support/super)
-- Remove a task from the marketplace, or restore a previously removed task.
-- Removal is only meaningful before the task is under an active booking, so
-- states with money/commitment attached (ASSIGNED..COMPLETED) are refused;
-- those are handled through the finance freeze/dispute path instead.
-- ---------------------------------------------------------------------------
create or replace function public.admin_moderate_task(
  p_task_id uuid,
  p_action text,
  p_reason text,
  p_idempotency_key text
)
returns public.tasks
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.tasks;
  v_cap user_capability;
  v_target task_status;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);
  if v_cap is null then
    raise exception 'FORBIDDEN: task moderation requires an active support/super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_action not in ('remove','restore') then
    raise exception 'INVALID_STATE: unsupported moderation action %', p_action
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.tasks where id = p_task_id for update;
  if not found then raise exception 'NOT_FOUND: task' using errcode = 'no_data_found'; end if;

  if exists (select 1 from public.moderation_actions ma
             where ma.resource_type = 'task' and ma.resource_id = p_task_id
               and ma.admin_id = auth.uid()
               and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  if p_action = 'remove' then
    if v_row.status = 'REMOVED' then return v_row; end if;
    if v_row.status in ('ASSIGNED','IN_PROGRESS','COMPLETION_REQUESTED','COMPLETED','DISPUTED') then
      raise exception 'INVALID_STATE: a task with an active or completed booking cannot be removed; use the dispute/freeze path.'
        using errcode = 'check_violation';
    end if;
    v_target := 'REMOVED';
  else
    if v_row.status <> 'REMOVED' then return v_row; end if;
    -- Restore to the pre-publication-neutral open state when it was published,
    -- otherwise back to draft ownership.
    v_target := case when v_row.published_at is null then 'DRAFT' else 'OPEN' end;
  end if;

  update public.tasks set status = v_target, updated_at = now()
    where id = p_task_id returning * into v_row;

  -- Hide/restore the task's media alongside the task itself so removed content
  -- does not remain reachable through media listings.
  if p_action = 'remove' then
    update public.task_media set moderation_status = 'HIDDEN'
      where task_id = p_task_id and moderation_status <> 'HIDDEN';
  else
    update public.task_media set moderation_status = 'PENDING'
      where task_id = p_task_id and moderation_status = 'HIDDEN';
  end if;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), v_cap, 'task', p_task_id, p_action, p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'to_status', v_target));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.task.' || p_action, 'task', p_task_id,
          jsonb_build_object('capability', v_cap, 'to_status', v_target,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

-- ---------------------------------------------------------------------------
-- Service catalog (Admin: super only)
-- Categories are referenced by every task, so the catalog is deliberately
-- restricted to ADMIN_SUPER and never hard-deletes: a category is deactivated
-- (hidden from the client picker) so existing task references stay valid.
-- ---------------------------------------------------------------------------
create or replace function public.admin_create_category(
  p_name text,
  p_slug text,
  p_reason text,
  p_idempotency_key text
)
returns public.categories
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.categories;
  v_slug text := lower(btrim(p_slug));
  v_name text := btrim(p_name);
  v_order integer;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  if not app.has_active_capability(array['ADMIN_SUPER']::user_capability[]) then
    raise exception 'FORBIDDEN: catalog changes require an active super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if v_name = '' or char_length(v_name) > 80 then
    raise exception 'VALIDATION_ERROR: category name must be 1..80 characters.'
      using errcode = 'check_violation';
  end if;
  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(v_slug) > 80 then
    raise exception 'VALIDATION_ERROR: slug must be lowercase alphanumeric words separated by single hyphens.'
      using errcode = 'check_violation';
  end if;

  -- Idempotent replay, and a friendly conflict for a slug already in use.
  select * into v_row from public.categories where slug = v_slug;
  if found then
    if exists (select 1 from public.moderation_actions ma
               where ma.resource_type = 'category' and ma.resource_id = v_row.id
                 and ma.action = 'create' and ma.admin_id = auth.uid()
                 and ma.metadata->>'idempotency_key' = p_idempotency_key) then
      return v_row;
    end if;
    raise exception 'CONFLICT: a category with this slug already exists.'
      using errcode = 'unique_violation';
  end if;

  select coalesce(max(sort_order), 0) + 1 into v_order from public.categories;

  insert into public.categories (slug, name, active, sort_order)
  values (v_slug, v_name, true, v_order)
  returning * into v_row;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), 'ADMIN_SUPER', 'category', v_row.id, 'create', p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'slug', v_slug, 'name', v_name));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.category.create', 'category', v_row.id,
          jsonb_build_object('capability', 'ADMIN_SUPER', 'slug', v_slug,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

create or replace function public.admin_rename_category(
  p_category_id uuid,
  p_name text,
  p_slug text,
  p_reason text,
  p_idempotency_key text
)
returns public.categories
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.categories;
  v_slug text := lower(btrim(p_slug));
  v_name text := btrim(p_name);
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  if not app.has_active_capability(array['ADMIN_SUPER']::user_capability[]) then
    raise exception 'FORBIDDEN: catalog changes require an active super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if v_name = '' or char_length(v_name) > 80 then
    raise exception 'VALIDATION_ERROR: category name must be 1..80 characters.'
      using errcode = 'check_violation';
  end if;
  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(v_slug) > 80 then
    raise exception 'VALIDATION_ERROR: slug must be lowercase alphanumeric words separated by single hyphens.'
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.categories where id = p_category_id for update;
  if not found then raise exception 'NOT_FOUND: category' using errcode = 'no_data_found'; end if;

  if (v_row.name = v_name and v_row.slug = v_slug)
     or exists (select 1 from public.moderation_actions ma
                where ma.resource_type = 'category' and ma.resource_id = p_category_id
                  and ma.action = 'rename' and ma.admin_id = auth.uid()
                  and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  if exists (select 1 from public.categories c where c.slug = v_slug and c.id <> p_category_id) then
    raise exception 'CONFLICT: a category with this slug already exists.'
      using errcode = 'unique_violation';
  end if;

  update public.categories set name = v_name, slug = v_slug
    where id = p_category_id returning * into v_row;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), 'ADMIN_SUPER', 'category', p_category_id, 'rename', p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'slug', v_slug, 'name', v_name));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.category.rename', 'category', p_category_id,
          jsonb_build_object('capability', 'ADMIN_SUPER', 'slug', v_slug,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

create or replace function public.admin_set_category_active(
  p_category_id uuid,
  p_active boolean,
  p_reason text,
  p_idempotency_key text
)
returns public.categories
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.categories;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  if not app.has_active_capability(array['ADMIN_SUPER']::user_capability[]) then
    raise exception 'FORBIDDEN: catalog changes require an active super Admin.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_row from public.categories where id = p_category_id for update;
  if not found then raise exception 'NOT_FOUND: category' using errcode = 'no_data_found'; end if;

  if v_row.active = p_active
     or exists (select 1 from public.moderation_actions ma
                where ma.resource_type = 'category' and ma.resource_id = p_category_id
                  and ma.action in ('activate','deactivate') and ma.admin_id = auth.uid()
                  and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  update public.categories set active = p_active
    where id = p_category_id returning * into v_row;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), 'ADMIN_SUPER', 'category', p_category_id,
          case when p_active then 'activate' else 'deactivate' end, p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'active', p_active));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.category.set_active', 'category', p_category_id,
          jsonb_build_object('capability', 'ADMIN_SUPER', 'active', p_active,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

create or replace function public.admin_reorder_category(
  p_category_id uuid,
  p_sort_order integer,
  p_reason text,
  p_idempotency_key text
)
returns public.categories
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.categories;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  if not app.has_active_capability(array['ADMIN_SUPER']::user_capability[]) then
    raise exception 'FORBIDDEN: catalog changes require an active super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_sort_order is null or p_sort_order < 0 or p_sort_order > 10000 then
    raise exception 'VALIDATION_ERROR: display order must be between 0 and 10000.'
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.categories where id = p_category_id for update;
  if not found then raise exception 'NOT_FOUND: category' using errcode = 'no_data_found'; end if;

  if v_row.sort_order = p_sort_order
     or exists (select 1 from public.moderation_actions ma
                where ma.resource_type = 'category' and ma.resource_id = p_category_id
                  and ma.action = 'reorder' and ma.admin_id = auth.uid()
                  and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  update public.categories set sort_order = p_sort_order
    where id = p_category_id returning * into v_row;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), 'ADMIN_SUPER', 'category', p_category_id, 'reorder', p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'sort_order', p_sort_order));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.category.reorder', 'category', p_category_id,
          jsonb_build_object('capability', 'ADMIN_SUPER', 'sort_order', p_sort_order,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

-- ---------------------------------------------------------------------------
-- Admin catalog history view.
-- The Admin category detail screen shows the change history for one category.
-- moderation_actions is already Admin-readable (0009), but this view keeps the
-- console's read shape stable and omits nothing sensitive (catalog changes
-- contain no third-party PII).
-- ---------------------------------------------------------------------------
create or replace view public.admin_category_history as
select ma.id, ma.resource_id as category_id, ma.action, ma.reason,
       ma.admin_id, ma.capability, ma.created_at
from public.moderation_actions ma
where ma.resource_type = 'category'
  and app.has_active_capability(array['ADMIN_SUPER']::user_capability[]);

grant select on public.admin_category_history to authenticated;

-- Grants: callable by authenticated sessions; each re-checks capability itself.
grant execute on function public.admin_set_account_status(uuid, account_status, text, text) to authenticated;
grant execute on function public.admin_moderate_task(uuid, text, text, text) to authenticated;
grant execute on function public.admin_create_category(text, text, text, text) to authenticated;
grant execute on function public.admin_rename_category(uuid, text, text, text, text) to authenticated;
grant execute on function public.admin_set_category_active(uuid, boolean, text, text) to authenticated;
grant execute on function public.admin_reorder_category(uuid, integer, text, text) to authenticated;


-- ===================================================================
-- 0017_offer_withdrawal.sql
-- ===================================================================

-- 0017_offer_withdrawal.sql
-- Offer withdrawal for the Tasker who submitted it.
--
-- 0009 gives `public.offers` an INSERT policy (plus the guarded `submit_offer`
-- RPC) and a SELECT policy, but no UPDATE policy for anyone. That left the
-- Offer System with no way for a Tasker to retract an offer they had not yet
-- won, even though the `offer_status` enum has a WITHDRAWN member and the
-- mobile port exposes the action.
--
-- A broad UPDATE policy on `offers` would be the wrong fix: it would also let a
-- Tasker rewrite their amount or message after the Client had read it, and it
-- could race with `select_offer`. Instead this is a narrow SECURITY DEFINER
-- command that can only ever move SUBMITTED -> WITHDRAWN for the calling
-- Tasker's own offer, and it locks the task row first so it cannot interleave
-- with offer selection.

create or replace function public.withdraw_offer(
  p_offer_id uuid,
  p_idempotency_key text
)
returns public.offers
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_offer public.offers;
  v_task  public.tasks;
begin
  if p_idempotency_key is null or btrim(p_idempotency_key) = ''
     or char_length(p_idempotency_key) > 200 then
    raise exception 'VALIDATION_ERROR: a non-empty idempotency key (1..200 chars) is required.'
      using errcode = 'check_violation';
  end if;

  select * into v_offer from public.offers where id = p_offer_id;
  if not found then
    raise exception 'NOT_FOUND: offer' using errcode = 'no_data_found';
  end if;

  -- Only the submitting Tasker may withdraw, and only on an active account.
  if v_offer.tasker_id <> auth.uid() then
    raise exception 'FORBIDDEN: only the submitting Tasker may withdraw this offer.'
      using errcode = 'insufficient_privilege';
  end if;
  if not app.is_active_account() then
    raise exception 'FORBIDDEN: account is not active.' using errcode = 'insufficient_privilege';
  end if;

  -- Idempotent: withdrawing an already-withdrawn offer is a no-op success.
  if v_offer.status = 'WITHDRAWN' then
    return v_offer;
  end if;

  -- Lock the task so this cannot interleave with select_offer choosing this
  -- very offer; re-read the offer under that lock before deciding.
  select * into v_task from public.tasks where id = v_offer.task_id for update;
  select * into v_offer from public.offers where id = p_offer_id for update;

  if v_offer.status = 'WITHDRAWN' then
    return v_offer;
  end if;
  if v_offer.status <> 'SUBMITTED' then
    raise exception 'INVALID_STATE: only a submitted offer can be withdrawn (current: %).', v_offer.status
      using errcode = 'check_violation';
  end if;

  update public.offers
    set status = 'WITHDRAWN', updated_at = now()
    where id = p_offer_id
    returning * into v_offer;

  insert into public.offer_events (offer_id, actor_id, event_type, metadata)
  values (p_offer_id, auth.uid(), 'withdrawn',
          jsonb_build_object('idempotency_key', p_idempotency_key));

  return v_offer;
end;
$$;

grant execute on function public.withdraw_offer(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Coordinate-readable location views.
--
-- `task_public_locations.approximate_point` and
-- `task_private_locations.exact_point` are `geography` columns. The only view
-- that exposes them as numbers is `public_task_feed`, which is restricted to
-- OPEN tasks — so an owner editing a DRAFT (or reviewing a task that has since
-- been assigned) had no way to read back the coordinates they saved.
--
-- Both views are `security_invoker = true`, so the caller's own RLS decides
-- visibility: the public one follows `task_public_locations_select` (owner,
-- participant, admin, or any OPEN task) and the private one follows
-- `task_private_locations_select` (owner or confirmed participant only). They
-- add no new access — they only make the stored point readable as lat/lng at
-- the same precision the feed already publishes.
-- ---------------------------------------------------------------------------

create or replace view public.task_locations_readable
with (security_invoker = true)
as
select
  pl.task_id,
  pl.city_code,
  pl.barangay_code,
  pl.landmark,
  round(st_y(pl.approximate_point::geometry)::numeric, 3) as approximate_lat,
  round(st_x(pl.approximate_point::geometry)::numeric, 3) as approximate_lng
from public.task_public_locations pl;

create or replace view public.task_private_locations_readable
with (security_invoker = true)
as
select
  pv.task_id,
  pv.exact_address,
  st_y(pv.exact_point::geometry) as exact_lat,
  st_x(pv.exact_point::geometry) as exact_lng
from public.task_private_locations pv;

grant select on public.task_locations_readable to authenticated;
grant select on public.task_private_locations_readable to authenticated;


-- ===================================================================
-- 0018_profile_self_service.sql
-- ===================================================================

-- 0018_profile_self_service.sql
-- Let an approved Tasker maintain their own public trust profile.
--
-- 0009 gives `public.tasker_profiles` a SELECT policy (`using (true)`) but no
-- UPDATE policy for anyone. The public bio and experience are written once by
-- `decide_tasker_application` at approval time, copied from the application, and
-- were then frozen forever — a Tasker could never correct a typo or refresh
-- their own description.
--
-- A self-UPDATE policy on the table would be too wide: the same row also holds
-- `completion_count`, `rating_sum`, `rating_count`, `approved_at`, and
-- `suspended_at`, which are platform-authoritative trust signals a Tasker must
-- never be able to edit. This RPC therefore updates exactly the two descriptive
-- columns and nothing else, and only for a Tasker whose profile is approved and
-- not suspended.

create or replace function public.update_tasker_public_profile(
  p_public_bio text,
  p_public_experience text
)
returns public.tasker_profiles
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.tasker_profiles;
  v_bio text := btrim(coalesce(p_public_bio, ''));
  v_experience text := btrim(coalesce(p_public_experience, ''));
begin
  if not app.is_active_account() then
    raise exception 'FORBIDDEN: account is not active.' using errcode = 'insufficient_privilege';
  end if;
  if not app.has_active_capability(array['TASKER']::user_capability[]) then
    raise exception 'FORBIDDEN: a Tasker capability is required.'
      using errcode = 'insufficient_privilege';
  end if;
  if char_length(v_bio) > 2000 or char_length(v_experience) > 2000 then
    raise exception 'VALIDATION_ERROR: bio and experience must each be at most 2000 characters.'
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.tasker_profiles where user_id = auth.uid() for update;
  if not found then
    raise exception 'NOT_FOUND: no Tasker profile for this account.' using errcode = 'no_data_found';
  end if;
  if v_row.approved_at is null or v_row.suspended_at is not null then
    raise exception 'FORBIDDEN: only an approved, unsuspended Tasker profile can be edited.'
      using errcode = 'insufficient_privilege';
  end if;

  update public.tasker_profiles
    set public_bio = v_bio, public_experience = v_experience
    where user_id = auth.uid()
    returning * into v_row;

  return v_row;
end;
$$;

grant execute on function public.update_tasker_public_profile(text, text) to authenticated;


-- ===================================================================
-- 0019_own_ledger_balances.sql
-- ===================================================================

-- 0019_own_ledger_balances.sql
-- Expose the caller's own derived ledger balances to the app.
--
-- `app.derive_user_balances(p_user_id)` computes the pending / protected /
-- available / reserved / withdrawn projection, but it lives in schema `app`,
-- which is deliberately NOT in PostgREST's exposed schemas and carries no
-- `authenticated` EXECUTE grant. A client calling `rpc('derive_user_balances')`
-- therefore always got HTTP 404, so the Tasker Dashboard balance could never
-- load.
--
-- The fix is a `public` wrapper that takes NO arguments. Exposing the existing
-- function directly would let any authenticated user pass an arbitrary
-- `p_user_id` and read another Tasker's earnings; binding the subject to
-- `auth.uid()` inside the body makes that impossible by construction.

create or replace function public.my_ledger_balances()
returns table (
  pending_centavos   bigint,
  protected_centavos bigint,
  available_centavos bigint,
  reserved_centavos  bigint,
  withdrawn_centavos bigint
)
language plpgsql
stable
security definer
set search_path = public, app
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'FORBIDDEN: authentication is required.'
      using errcode = 'insufficient_privilege';
  end if;

  -- Subject is always the caller. There is no parameter to tamper with.
  return query select * from app.derive_user_balances(v_user);
end;
$$;

grant execute on function public.my_ledger_balances() to authenticated;


-- ===================================================================
-- 0020_notification_emission.sql
-- ===================================================================

-- 0020_notification_emission.sql
-- Actually produce the notifications the apps already read.
--
-- Before this migration the entire schema contained exactly two notification
-- inserts, both inside payment-driven RPCs. The mobile app models eleven
-- notification types; nine of them were never written, so a user's inbox stayed
-- empty no matter what happened to their tasks, offers, or bookings.
--
-- Implemented as AFTER triggers rather than by editing the existing RPCs:
--
--   * A trigger fires for every path that changes the row, including Admin
--     commands and future service-role automation, so a notification cannot be
--     missed by a code path someone forgets to update.
--   * The alternative meant redefining `process_payment_event` and
--     `confirm_completion_and_release` — long, finance-critical functions that
--     move money through the balanced ledger. Rewriting those to change a
--     notification label would be a poor risk trade.
--
-- `public.notifications` has no INSERT policy, so an authenticated user cannot
-- forge a notification. `app.notify` is SECURITY DEFINER and is the only way
-- rows are created.

-- ---------------------------------------------------------------------------
-- Allow the 'reviews' preference category.
--
-- The apps have always offered a Reviews toggle, but the original CHECK list
-- omitted it, so the upsert was rejected and the switch silently snapped back.
-- Widening the constraint is additive: every previously valid value stays valid.
-- ---------------------------------------------------------------------------
alter table public.notification_preferences
  drop constraint if exists notification_preferences_category_check;

alter table public.notification_preferences
  add constraint notification_preferences_category_check
  check (category in
    ('verification', 'offers', 'bookings', 'payments', 'messages', 'disputes', 'reviews', 'system'));

-- ---------------------------------------------------------------------------
-- Preference category for an event type.
--
-- `notification_preferences.category` is a coarse grouping the user toggles;
-- `notifications.type` is the specific event. This maps one to the other so a
-- user who mutes "offers" stops receiving both OFFER_RECEIVED and OFFER_SELECTED.
-- ---------------------------------------------------------------------------
create or replace function app.notification_category(p_type text)
returns text
language sql
immutable
as $$
  select case p_type
    when 'OFFER_RECEIVED'         then 'offers'
    when 'OFFER_SELECTED'         then 'offers'
    when 'PAYMENT_CONFIRMED'      then 'payments'
    when 'PAYMENT_FAILED'         then 'payments'
    when 'BOOKING_STARTED'        then 'bookings'
    when 'COMPLETION_REQUESTED'   then 'bookings'
    when 'BOOKING_COMPLETED'      then 'bookings'
    when 'DISPUTE_OPENED'         then 'disputes'
    when 'REVIEW_RECEIVED'        then 'reviews'
    when 'MESSAGE_RECEIVED'       then 'messages'
    when 'VERIFICATION_DECISION'  then 'verification'
    else 'system'
  end;
$$;

-- ---------------------------------------------------------------------------
-- Create one in-app notification, honouring the recipient's preference.
--
-- Silent no-ops are deliberate: a missing recipient, or a recipient who muted
-- the category, must not fail the surrounding transaction. Losing a task state
-- change because a notification could not be delivered would be the wrong
-- trade — the state change is the important part.
-- ---------------------------------------------------------------------------
create or replace function app.notify(
  p_user_id       uuid,
  p_type          text,
  p_title         text,
  p_body          text,
  p_resource_type text,
  p_resource_id   uuid
)
returns void
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_category text := app.notification_category(p_type);
  v_in_app   boolean;
begin
  if p_user_id is null then return; end if;

  -- Absent row means "not configured", which the table defaults to enabled.
  select np.in_app into v_in_app
  from public.notification_preferences np
  where np.user_id = p_user_id and np.category = v_category;

  if v_in_app is false then return; end if;

  insert into public.notifications
    (user_id, type, title, body, resource_type, resource_id, delivery_status)
  values
    (p_user_id, p_type, p_title, p_body, p_resource_type, p_resource_id, 'PENDING');
end;
$$;

-- ---------------------------------------------------------------------------
-- Offers: the Client learns an offer arrived; the Tasker learns they were chosen.
-- ---------------------------------------------------------------------------
create or replace function app.tg_notify_offer_received()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_task public.tasks;
begin
  select * into v_task from public.tasks where id = new.task_id;
  if not found then return new; end if;

  -- A Client offering on their own task would be notified about themselves.
  if v_task.client_id = new.tasker_id then return new; end if;

  perform app.notify(
    v_task.client_id,
    'OFFER_RECEIVED',
    'New offer received',
    format('You have a new offer on "%s".', v_task.title),
    'task',
    v_task.id
  );
  return new;
end;
$$;

drop trigger if exists trg_notify_offer_received on public.offers;
create trigger trg_notify_offer_received
  after insert on public.offers
  for each row execute function app.tg_notify_offer_received();

create or replace function app.tg_notify_offer_decided()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_task public.tasks;
begin
  if new.status = old.status then return new; end if;
  if new.status <> 'SELECTED' then return new; end if;

  select * into v_task from public.tasks where id = new.task_id;

  perform app.notify(
    new.tasker_id,
    'OFFER_SELECTED',
    'Your offer was accepted',
    format('The client chose your offer on "%s".', coalesce(v_task.title, 'a task')),
    'task',
    new.task_id
  );
  return new;
end;
$$;

drop trigger if exists trg_notify_offer_decided on public.offers;
create trigger trg_notify_offer_decided
  after update of status on public.offers
  for each row execute function app.tg_notify_offer_decided();

-- ---------------------------------------------------------------------------
-- Bookings: both sides follow the work as it progresses.
-- ---------------------------------------------------------------------------
create or replace function app.tg_notify_booking_status()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_title text;
begin
  if new.status = old.status then return new; end if;
  select t.title into v_title from public.tasks t where t.id = new.task_id;
  v_title := coalesce(v_title, 'your booking');

  if new.status = 'IN_PROGRESS' then
    perform app.notify(new.client_id, 'BOOKING_STARTED', 'Work has started',
      format('Your Tasker started work on "%s".', v_title), 'booking', new.id);

  elsif new.status = 'COMPLETION_REQUESTED' then
    perform app.notify(new.client_id, 'COMPLETION_REQUESTED', 'Confirm completion',
      format('Your Tasker marked "%s" as done. Please review and confirm.', v_title),
      'booking', new.id);

  elsif new.status = 'COMPLETED' then
    -- The Tasker's "funds released" notice is already emitted by
    -- confirm_completion_and_release; this closes the loop for the Client.
    perform app.notify(new.client_id, 'BOOKING_COMPLETED', 'Booking completed',
      format('"%s" is complete. Leave a review to help other clients.', v_title),
      'booking', new.id);

  elsif new.status = 'PAYMENT_FAILED' then
    perform app.notify(new.client_id, 'PAYMENT_FAILED', 'Payment failed',
      format('Payment for "%s" did not go through.', v_title), 'booking', new.id);
  end if;

  return new;
end;
$$;

drop trigger if exists trg_notify_booking_status on public.bookings;
create trigger trg_notify_booking_status
  after update of status on public.bookings
  for each row execute function app.tg_notify_booking_status();

-- ---------------------------------------------------------------------------
-- Disputes: the participant who did not open it needs to know.
-- ---------------------------------------------------------------------------
create or replace function app.tg_notify_dispute_opened()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_booking public.bookings;
  v_other   uuid;
begin
  select * into v_booking from public.bookings where id = new.booking_id;
  if not found then return new; end if;

  v_other := case when new.opened_by = v_booking.client_id
                  then v_booking.tasker_id else v_booking.client_id end;

  perform app.notify(v_other, 'DISPUTE_OPENED', 'A dispute was opened',
    'A dispute was opened on one of your bookings. Support will review it.',
    'dispute', new.id);
  return new;
end;
$$;

drop trigger if exists trg_notify_dispute_opened on public.disputes;
create trigger trg_notify_dispute_opened
  after insert on public.disputes
  for each row execute function app.tg_notify_dispute_opened();

-- ---------------------------------------------------------------------------
-- Reviews: the reviewee is told a review exists, never its contents.
--
-- Reviews are double-blind until both sides submit, so the body deliberately
-- carries no score or comment.
-- ---------------------------------------------------------------------------
create or replace function app.tg_notify_review_received()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
begin
  perform app.notify(new.reviewee_id, 'REVIEW_RECEIVED', 'You received a review',
    'A review was submitted for one of your completed bookings.',
    'review', new.id);
  return new;
end;
$$;

drop trigger if exists trg_notify_review_received on public.reviews;
create trigger trg_notify_review_received
  after insert on public.reviews
  for each row execute function app.tg_notify_review_received();

-- ---------------------------------------------------------------------------
-- Messages: every other participant of the conversation.
-- ---------------------------------------------------------------------------
create or replace function app.tg_notify_message_received()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_participant uuid;
begin
  for v_participant in
    select cp.user_id
    from public.conversation_participants cp
    where cp.conversation_id = new.conversation_id
      and cp.user_id <> new.sender_id
  loop
    perform app.notify(v_participant, 'MESSAGE_RECEIVED', 'New message',
      'You have a new message about one of your bookings.',
      'conversation', new.conversation_id);
  end loop;
  return new;
end;
$$;

drop trigger if exists trg_notify_message_received on public.messages;
create trigger trg_notify_message_received
  after insert on public.messages
  for each row execute function app.tg_notify_message_received();

-- ---------------------------------------------------------------------------
-- Identity verification and Tasker applications: the subject learns the outcome.
--
-- The decision reason is not included: it can contain reviewer notes, and the
-- app fetches the case detail when the user opens it.
-- ---------------------------------------------------------------------------
create or replace function app.tg_notify_verification_decision()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
begin
  if new.status = old.status then return new; end if;
  if new.status not in ('APPROVED', 'REJECTED', 'RESUBMISSION_REQUIRED') then
    return new;
  end if;

  perform app.notify(new.user_id, 'VERIFICATION_DECISION',
    case new.status
      when 'APPROVED' then 'Identity verified'
      when 'REJECTED' then 'Identity verification rejected'
      else 'More information needed'
    end,
    case new.status
      when 'APPROVED' then 'Your identity is verified. You can now post tasks.'
      when 'REJECTED' then 'Your identity verification was not approved. Open the app for details.'
      else 'Please resubmit your identity documents.'
    end,
    null::text, null::uuid);
  return new;
end;
$$;

drop trigger if exists trg_notify_verification_decision on public.verification_cases;
create trigger trg_notify_verification_decision
  after update of status on public.verification_cases
  for each row execute function app.tg_notify_verification_decision();

create or replace function app.tg_notify_tasker_decision()
returns trigger
language plpgsql
security definer
set search_path = public, app
as $$
begin
  if new.status = old.status then return new; end if;
  if new.status not in ('APPROVED', 'REJECTED', 'RESUBMISSION_REQUIRED', 'SUSPENDED') then
    return new;
  end if;

  perform app.notify(new.user_id, 'VERIFICATION_DECISION',
    case new.status
      when 'APPROVED'  then 'You are an approved Tasker'
      when 'REJECTED'  then 'Tasker application not approved'
      when 'SUSPENDED' then 'Tasker access suspended'
      else 'More information needed'
    end,
    case new.status
      when 'APPROVED'  then 'You can now browse work and submit offers.'
      when 'REJECTED'  then 'Your Tasker application was not approved. Open the app for details.'
      when 'SUSPENDED' then 'Your Tasker access is suspended. Contact support for details.'
      else 'Please update and resubmit your Tasker application.'
    end,
    null::text, null::uuid);
  return new;
end;
$$;

drop trigger if exists trg_notify_tasker_decision on public.tasker_applications;
create trigger trg_notify_tasker_decision
  after update of status on public.tasker_applications
  for each row execute function app.tg_notify_tasker_decision();

-- ---------------------------------------------------------------------------
-- Grants. The helpers are invoked only from SECURITY DEFINER trigger bodies,
-- which execute as the owner, so no role needs EXECUTE. Revoking keeps a
-- client from minting notifications for another user.
-- ---------------------------------------------------------------------------
revoke execute on function app.notify(uuid, text, text, text, text, uuid)
  from public, anon, authenticated, service_role;
revoke execute on function app.notification_category(text)
  from public, anon, authenticated, service_role;


-- ===================================================================
-- 0021_verification_submission_and_review_reveal.sql
-- ===================================================================

-- 0021_verification_submission_and_review_reveal.sql
--
-- Two gaps that both blocked real user flows.
--
-- 1. Identity verification could not be submitted at all. RLS lets a user
--    insert their own case (only in status DRAFT) and its documents, but there
--    is no UPDATE policy, so nothing could move DRAFT -> SUBMITTED. Admins had
--    `decide_verification`; users had no way to reach the queue. Verification is
--    a hard precondition for publishing a task and for offering on one, so this
--    made the entire marketplace unreachable for a genuinely new account.
--
-- 2. Blind reviews could deadlock. `submit_review` reveals both reviews when the
--    second one arrives, so a booking where only one side ever reviews stays
--    hidden forever and the review is never published. The apps model a reveal
--    deadline, but nothing in the database implemented it.
--
-- Both are exposed as `public` SECURITY DEFINER functions that derive the
-- subject from `auth.uid()`. Neither takes a user id parameter, so neither can
-- be pointed at somebody else's case or booking.

-- ===========================================================================
-- Identity verification submission
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- The caller's active case, created on demand.
--
-- `uq_verification_active_case` permits one non-terminal case per user, so a
-- plain insert races with itself and fails the second time. Callers need an
-- idempotent "give me the case I should attach documents to" entry point, which
-- is also what supplies the storage scope id for the upload path.
-- ---------------------------------------------------------------------------
create or replace function public.start_verification()
returns public.verification_cases
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_user uuid := auth.uid();
  v_case public.verification_cases;
begin
  if v_user is null then
    raise exception 'FORBIDDEN: authentication is required.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_case
  from public.verification_cases
  where user_id = v_user
    and status in ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'RESUBMISSION_REQUIRED')
  limit 1;
  if found then return v_case; end if;

  -- An already-approved user has no active case and needs no new one.
  if exists (select 1 from public.verification_cases
             where user_id = v_user and status = 'APPROVED') then
    select * into v_case
    from public.verification_cases
    where user_id = v_user and status = 'APPROVED'
    order by decided_at desc nulls last
    limit 1;
    return v_case;
  end if;

  insert into public.verification_cases (user_id, status)
  values (v_user, 'DRAFT')
  returning * into v_case;

  insert into public.verification_events (case_id, from_status, to_status, actor_id)
  values (v_case.id, null, 'DRAFT', v_user);

  return v_case;
exception
  when unique_violation then
    -- Lost the race against a concurrent call; the winner's case is the answer.
    select * into v_case
    from public.verification_cases
    where user_id = v_user
      and status in ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'RESUBMISSION_REQUIRED')
    limit 1;
    return v_case;
end;
$$;

-- ---------------------------------------------------------------------------
-- Hand the caller's case to the Admin review queue.
--
-- Documents must have been added since the last decision. Without that clause a
-- user asked to resubmit could re-send the same rejected photos by pressing
-- Submit again, and the Admin queue would fill with unchanged cases.
-- ---------------------------------------------------------------------------
create or replace function public.submit_verification()
returns public.verification_cases
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_user  uuid := auth.uid();
  v_case  public.verification_cases;
  v_prev  verification_status;
  v_since timestamptz;
begin
  if v_user is null then
    raise exception 'FORBIDDEN: authentication is required.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_case
  from public.verification_cases
  where user_id = v_user
    and status in ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'RESUBMISSION_REQUIRED')
  limit 1
  for update;

  if not found then
    raise exception 'NOT_FOUND: no verification case to submit.'
      using errcode = 'no_data_found';
  end if;

  -- Already queued: return it rather than pushing a duplicate at the reviewers.
  if v_case.status in ('SUBMITTED', 'IN_REVIEW') then
    return v_case;
  end if;

  v_prev  := v_case.status;
  v_since := coalesce(v_case.decided_at, '-infinity'::timestamptz);

  if not exists (
    select 1 from public.verification_documents
    where case_id = v_case.id and kind = 'government_id_front' and created_at > v_since
  ) then
    raise exception 'VALIDATION_ERROR: a photo of your government ID is required.'
      using errcode = 'check_violation';
  end if;

  if not exists (
    select 1 from public.verification_documents
    where case_id = v_case.id and kind = 'selfie' and created_at > v_since
  ) then
    raise exception 'VALIDATION_ERROR: a selfie is required.'
      using errcode = 'check_violation';
  end if;

  update public.verification_cases
     set status = 'SUBMITTED',
         submitted_at = now(),
         -- A resubmission is a new attempt; the version makes that auditable.
         version = case when v_prev = 'RESUBMISSION_REQUIRED'
                        then v_case.version + 1 else v_case.version end,
         decision_reason = null
   where id = v_case.id
  returning * into v_case;

  insert into public.verification_events (case_id, from_status, to_status, actor_id)
  values (v_case.id, v_prev, 'SUBMITTED', v_user);

  return v_case;
end;
$$;

grant execute on function public.start_verification() to authenticated;
grant execute on function public.submit_verification() to authenticated;

-- ===========================================================================
-- Blind review reveal
-- ===========================================================================

insert into public.app_settings (key, typed_value)
values ('review_reveal_days', '14'::jsonb)
on conflict (key) do nothing;

create or replace function app.review_reveal_days()
returns integer
language sql
stable
as $$
  select greatest(1, coalesce(
    (select (typed_value #>> '{}')::integer
     from public.app_settings where key = 'review_reveal_days'),
    14));
$$;

-- ---------------------------------------------------------------------------
-- Read the caller's review pair for a booking, revealing anything now due.
--
-- Revealing lazily on read rather than from a scheduled job keeps the rule in
-- one place and needs no extension: the only moment the reveal state matters is
-- when somebody looks. `submit_review` still reveals immediately when the second
-- review lands, so the deadline only ever resolves the one-sided case.
--
-- The counterpart's review is withheld unless its status is REVEALED, so a
-- moderated review is never surfaced either.
-- ---------------------------------------------------------------------------
create or replace function public.get_review_pair(p_booking_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_booking  public.bookings;
  v_first    timestamptz;
  v_count    integer;
  v_deadline timestamptz;
  v_mine     public.reviews;
  v_other    public.reviews;
  v_has_mine boolean := false;
  v_has_other boolean := false;
begin
  if auth.uid() is null then
    raise exception 'FORBIDDEN: authentication is required.'
      using errcode = 'insufficient_privilege';
  end if;

  select * into v_booking from public.bookings where id = p_booking_id;
  if not found then
    raise exception 'NOT_FOUND: booking %', p_booking_id using errcode = 'no_data_found';
  end if;
  if auth.uid() <> v_booking.client_id and auth.uid() <> v_booking.tasker_id then
    raise exception 'FORBIDDEN: only booking participants may read its reviews.'
      using errcode = 'insufficient_privilege';
  end if;

  select min(submitted_at), count(*) into v_first, v_count
  from public.reviews where booking_id = p_booking_id;

  if v_first is not null then
    v_deadline := v_first + make_interval(days => app.review_reveal_days());
  end if;

  if v_count >= 2 or (v_deadline is not null and v_deadline <= now()) then
    update public.reviews
       set status = 'REVEALED',
           revealed_at = coalesce(revealed_at, now())
     where booking_id = p_booking_id and status = 'HIDDEN';
  end if;

  select * into v_mine
  from public.reviews
  where booking_id = p_booking_id and reviewer_id = auth.uid();
  v_has_mine := found;

  select * into v_other
  from public.reviews
  where booking_id = p_booking_id and reviewer_id <> auth.uid();
  v_has_other := found;

  return jsonb_build_object(
    'booking_id', p_booking_id,
    'reveal_deadline', v_deadline,
    'both_submitted', v_count >= 2,
    'my_review', case when v_has_mine then to_jsonb(v_mine) else null end,
    'counterpart_review',
      case when v_has_other and v_other.status = 'REVEALED'
           then to_jsonb(v_other) else null end
  );
end;
$$;

grant execute on function public.get_review_pair(uuid) to authenticated;
revoke execute on function app.review_reveal_days() from public, anon, authenticated, service_role;


-- ===================================================================
-- 0022_realtime_publication.sql
-- ===================================================================

-- 0022_realtime_publication.sql
-- Let chat and the notification bell update without polling.
--
-- Supabase Realtime streams from the `supabase_realtime` publication. A table
-- that is not a member emits nothing, so a client subscription silently
-- receives no events — which is why chat had to be re-fetched by hand.
--
-- Only two tables are added, and both already carry restrictive RLS:
--
--   * `messages` — `postgres_changes` re-evaluates the table's SELECT policy per
--     subscriber, so a user receives an event only for a conversation they are
--     already allowed to read. Membership does not widen access.
--   * `notifications` — SELECT is limited to `user_id = auth.uid()`.
--
-- Deliberately excluded: `message_media` (no `conversation_id` to filter on, and
-- it commits in the same transaction as its message, so the message event is
-- already enough to trigger a refetch that includes it) and every finance table,
-- where a stream of ledger movements would be an unnecessary exposure.
--
-- `alter publication ... add table` errors if the table is already a member, so
-- each add is guarded to keep this migration re-runnable.
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'messages'
  ) then
    alter publication supabase_realtime add table public.messages;
  end if;

  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'notifications'
  ) then
    alter publication supabase_realtime add table public.notifications;
  end if;
exception
  when undefined_object then
    -- A self-hosted database without the Supabase Realtime publication is a
    -- valid target; the apps fall back to explicit refresh in that case.
    raise notice 'supabase_realtime publication not found; skipping realtime setup.';
end;
$$;

-- Realtime sends the old row for UPDATE/DELETE only when the replica identity
-- exposes it. Chat needs inserts, so the default (primary key) is enough here.


-- ===================================================================
-- 0023_review_moderation.sql
-- ===================================================================

-- 0023_review_moderation.sql
-- Give Admins a way to act on an abusive review.
--
-- `review_status` has always had a MODERATED state and `reviews` has always been
-- Admin-readable, but nothing could set it: there is no Admin UPDATE policy on
-- the table and no RPC. A review containing harassment or personal information
-- was therefore permanent once revealed.
--
-- Hiding a review must also correct the rating aggregate. `submit_review`
-- increments `tasker_profiles.rating_sum` / `rating_count` when the review is
-- created, so leaving those untouched would keep a retracted 1-star review
-- weighing on a Tasker's average while its text was no longer visible — the
-- worst of both outcomes.

-- ---------------------------------------------------------------------------
-- Admin review queue.
--
-- Follows the 0013 queue-view pattern: the capability predicate lives in the
-- view, so a non-Admin session selecting from it gets zero rows rather than
-- relying on a grant being withheld.
-- ---------------------------------------------------------------------------
create or replace view public.admin_review_queue as
select r.id,
       r.booking_id,
       b.task_id,
       t.title as task_title,
       r.reviewer_id,
       r.reviewee_id,
       r.score,
       r.comment,
       r.status,
       r.submitted_at,
       r.revealed_at
from public.reviews r
join public.bookings b on b.id = r.booking_id
join public.tasks t on t.id = b.task_id
where app.has_active_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);

grant select on public.admin_review_queue to authenticated;

-- ---------------------------------------------------------------------------
-- admin_moderate_review (Admin: support/super)
--
-- `hide` moves a review to MODERATED and withdraws its score from the reviewee's
-- aggregate; `restore` reverses both. Same contract as the other 0016 admin
-- commands: active capability, bounded reason plus idempotency key, row lock,
-- and a replay that returns the current row without writing a second audit
-- entry (which would also double-apply the aggregate correction).
-- ---------------------------------------------------------------------------
create or replace function public.admin_moderate_review(
  p_review_id uuid,
  p_action text,
  p_reason text,
  p_idempotency_key text
)
returns public.reviews
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.reviews;
  v_cap user_capability;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);
  if v_cap is null then
    raise exception 'FORBIDDEN: review moderation requires an active support/super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_action not in ('hide','restore') then
    raise exception 'INVALID_STATE: unsupported moderation action %', p_action
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.reviews where id = p_review_id for update;
  if not found then raise exception 'NOT_FOUND: review' using errcode = 'no_data_found'; end if;

  if exists (select 1 from public.moderation_actions ma
             where ma.resource_type = 'review' and ma.resource_id = p_review_id
               and ma.admin_id = auth.uid()
               and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  if p_action = 'hide' then
    if v_row.status = 'MODERATED' then return v_row; end if;

    update public.reviews set status = 'MODERATED' where id = p_review_id returning * into v_row;

    -- `greatest`/`least` keep the non-negative CHECK constraints satisfied even
    -- if an aggregate was ever corrected by hand.
    update public.tasker_profiles
       set rating_sum   = greatest(0, rating_sum - v_row.score),
           rating_count = greatest(0, rating_count - 1)
     where user_id = v_row.reviewee_id;
  else
    if v_row.status <> 'MODERATED' then return v_row; end if;

    -- A review that was never revealed goes back to HIDDEN, not REVEALED: the
    -- blind window is the counterpart's, not the Admin's, to end.
    update public.reviews
       set status = case when v_row.revealed_at is null then 'HIDDEN' else 'REVEALED' end
     where id = p_review_id
    returning * into v_row;

    update public.tasker_profiles
       set rating_sum   = rating_sum + v_row.score,
           rating_count = rating_count + 1
     where user_id = v_row.reviewee_id;
  end if;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), v_cap, 'review', p_review_id, p_action, p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'to_status', v_row.status));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.review.' || p_action, 'review', p_review_id,
          jsonb_build_object('capability', v_cap, 'to_status', v_row.status,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

grant execute on function public.admin_moderate_review(uuid, text, text, text) to authenticated;


-- ===================================================================
-- 0024_task_feed_geo_search.sql
-- ===================================================================

-- 0024_task_feed_geo_search.sql
-- Make "near me" actually mean near me.
--
-- PostGIS has been installed since 0001 and `task_public_locations` has carried
-- a `geography(Point,4326)` column with a GIST index since 0004, but no query in
-- the schema ever used a distance operator. `search_open_tasks` (0008) has no
-- coordinate parameters at all, and the mobile client accepted `nearLat`,
-- `nearLng`, and `radiusKm` only to drop them and order by recency instead. A
-- Tasker filtering to "within 5 km" was shown the whole city.
--
-- Radius filtering cannot be expressed through PostgREST's filter grammar, so it
-- has to be a function. This one replaces `search_open_tasks` as the single feed
-- entry point rather than sitting beside it, because the contract requires the
-- list and the map to agree: two query paths would eventually disagree.
--
-- Privacy: distance is measured from `approximate_point`, the same fuzzed point
-- the public feed already publishes, never from `task_private_locations`. It is
-- also rounded to 100 m so a set of distance readings cannot be trilaterated
-- into a sharper position than the coordinates the feed already returns.
--
-- `security invoker` is deliberate — the caller's RLS on `tasks` and
-- `task_public_locations` still decides which rows are visible. This function
-- adds filtering and ordering, never reach.

create or replace function public.search_task_feed(
  p_keyword        text default null,
  p_category_id    uuid default null,
  p_city_code      text default null,
  p_barangay_code  text default null,
  p_min_budget     bigint default null,
  p_max_budget     bigint default null,
  p_scheduled_from timestamptz default null,
  p_scheduled_to   timestamptz default null,
  p_same_day_only  boolean default false,
  p_near_lat       double precision default null,
  p_near_lng       double precision default null,
  p_radius_km      double precision default null,
  p_sort           text default 'newest',
  p_page           integer default 1,
  p_page_size      integer default 20
)
returns table (
  id               uuid,
  category_id      uuid,
  title            text,
  description      text,
  budget_centavos  bigint,
  currency         text,
  status           task_status,
  same_day         boolean,
  scheduled_for    timestamptz,
  published_at     timestamptz,
  city_code        text,
  barangay_code    text,
  landmark         text,
  approximate_lat  numeric,
  approximate_lng  numeric,
  offer_count      bigint,
  distance_m       double precision,
  total_count      bigint
)
language sql
stable
security invoker
set search_path = public
as $$
with bounds as (
  select
    -- Page size is clamped server-side so a client cannot ask for the whole table.
    least(greatest(coalesce(p_page_size, 20), 1), 100) as page_size,
    greatest(coalesce(p_page, 1), 1)                   as page,
    -- A coordinate pair is only usable if both halves are present and in range;
    -- a half-supplied origin silently degrades to a non-geographic search
    -- rather than matching everything or nothing.
    case
      when p_near_lat is null or p_near_lng is null then null
      when p_near_lat < -90 or p_near_lat > 90 then null
      when p_near_lng < -180 or p_near_lng > 180 then null
      else st_setsrid(st_makepoint(p_near_lng, p_near_lat), 4326)::geography
    end as origin,
    -- Unbounded radius searches scan the country; 100 km covers any realistic
    -- travel distance for a task in a Philippine city.
    case
      when p_radius_km is null or p_radius_km <= 0 then null
      else least(p_radius_km, 100) * 1000
    end as radius_m
),
matched as (
  select
    f.*,
    -- st_distance on geography returns metres.
    case when b.origin is null then null
         else round(st_distance(f.approximate_point, b.origin) / 100.0) * 100
    end as distance_m,
    b.page_size,
    b.page,
    b.origin
  from public.public_task_feed f
  cross join bounds b
  where (p_keyword is null
         or f.title ilike '%' || p_keyword || '%'
         or f.description ilike '%' || p_keyword || '%')
    and (p_category_id is null or f.category_id = p_category_id)
    and (p_city_code is null or f.city_code = p_city_code)
    and (p_barangay_code is null or f.barangay_code = p_barangay_code)
    and (p_min_budget is null or f.budget_centavos >= p_min_budget)
    and (p_max_budget is null or f.budget_centavos <= p_max_budget)
    and (p_scheduled_from is null or f.scheduled_for >= p_scheduled_from)
    and (p_scheduled_to is null or f.scheduled_for <= p_scheduled_to)
    and (p_same_day_only is not true or f.same_day = true)
    -- st_dwithin is the index-using form; a radius without an origin is ignored
    -- rather than treated as "0 km", which would return nothing.
    and (b.origin is null or b.radius_m is null
         or st_dwithin(f.approximate_point, b.origin, b.radius_m))
)
select
  m.id,
  m.category_id,
  m.title,
  m.description,
  m.budget_centavos,
  m.currency,
  m.status,
  m.same_day,
  m.scheduled_for,
  m.published_at,
  m.city_code,
  m.barangay_code,
  m.landmark,
  m.approximate_lat,
  m.approximate_lng,
  m.offer_count,
  m.distance_m,
  count(*) over () as total_count
from matched m
order by
  -- 'nearby' without a usable origin falls back to recency instead of
  -- inventing an order the caller would read as distance.
  case when p_sort = 'nearby' and m.origin is not null then m.distance_m end asc nulls last,
  case when p_sort = 'highest_budget' then m.budget_centavos end desc nulls last,
  m.published_at desc nulls last,
  m.id
limit  (select page_size from bounds)
offset ((select page from bounds) - 1) * (select page_size from bounds);
$$;

grant execute on function public.search_task_feed(
  text, uuid, text, text, bigint, bigint, timestamptz, timestamptz, boolean,
  double precision, double precision, double precision, text, integer, integer
) to authenticated, anon;


-- ===================================================================
-- 0025_media_moderation.sql
-- ===================================================================

-- 0025_media_moderation.sql
-- Let an Admin act on a single photo instead of the whole task.
--
-- `task_media.moderation_status` has existed since 0004 with four states, but the
-- only thing that ever wrote it was `admin_moderate_task` (0016), which flips
-- every row for a task at once. So a task with nine acceptable photos and one
-- inappropriate photo had exactly two outcomes: leave the bad photo published,
-- or remove the entire task and the Client's work with it. Neither is a
-- proportionate moderation response.
--
-- Only APPROVED and HIDDEN are reachable here. REJECTED exists in the enum but
-- is indistinguishable from HIDDEN in behaviour and would only create ambiguity
-- about which state means "not visible"; PENDING is the insert default and is
-- not something an Admin needs to set back.

-- ---------------------------------------------------------------------------
-- Media moderation queue.
--
-- Capability predicate lives in the view, matching the 0013 queue pattern: a
-- non-Admin session selecting from it gets zero rows rather than depending on a
-- grant being withheld.
--
-- `storage_path` is exposed because moderating an image requires fetching it,
-- and the only way to do that is `admin_authorize_object_read` plus a signed
-- URL, which needs the key. The bucket stays private throughout.
-- ---------------------------------------------------------------------------
create or replace view public.admin_task_media_queue as
select tm.id,
       tm.task_id,
       t.title as task_title,
       t.status as task_status,
       t.client_id,
       tm.storage_path,
       tm.kind,
       tm.moderation_status,
       tm.sort_order,
       tm.created_at
from public.task_media tm
join public.tasks t on t.id = tm.task_id
where app.has_active_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);

grant select on public.admin_task_media_queue to authenticated;

-- ---------------------------------------------------------------------------
-- admin_moderate_task_media (Admin: support/super)
--
-- Same contract as the other 0016 admin commands: active capability, bounded
-- reason plus idempotency key, row lock, and a replay that returns the current
-- row without a second audit write.
-- ---------------------------------------------------------------------------
create or replace function public.admin_moderate_task_media(
  p_media_id uuid,
  p_action text,
  p_reason text,
  p_idempotency_key text
)
returns public.task_media
language plpgsql
security definer
set search_path = public, app
as $$
declare
  v_row public.task_media;
  v_cap user_capability;
  v_target moderation_status;
begin
  perform app.assert_reasoned(p_reason, p_idempotency_key);
  v_cap := app.acting_capability(array['ADMIN_SUPPORT','ADMIN_SUPER']::user_capability[]);
  if v_cap is null then
    raise exception 'FORBIDDEN: media moderation requires an active support/super Admin.'
      using errcode = 'insufficient_privilege';
  end if;
  if p_action not in ('approve','hide') then
    raise exception 'INVALID_STATE: unsupported moderation action %', p_action
      using errcode = 'check_violation';
  end if;

  select * into v_row from public.task_media where id = p_media_id for update;
  if not found then raise exception 'NOT_FOUND: task media' using errcode = 'no_data_found'; end if;

  if exists (select 1 from public.moderation_actions ma
             where ma.resource_type = 'task_media' and ma.resource_id = p_media_id
               and ma.admin_id = auth.uid()
               and ma.metadata->>'idempotency_key' = p_idempotency_key) then
    return v_row;
  end if;

  v_target := case when p_action = 'approve' then 'APPROVED' else 'HIDDEN' end;
  if v_row.moderation_status = v_target then return v_row; end if;

  update public.task_media set moderation_status = v_target
    where id = p_media_id returning * into v_row;

  insert into public.moderation_actions (admin_id, capability, resource_type, resource_id, action, reason, metadata)
  values (auth.uid(), v_cap, 'task_media', p_media_id, p_action, p_reason,
          jsonb_build_object('idempotency_key', p_idempotency_key,
                             'to_status', v_target, 'task_id', v_row.task_id));
  insert into public.audit_logs (actor_id, action, resource_type, resource_id, safe_metadata)
  values (auth.uid(), 'admin.task_media.' || p_action, 'task_media', p_media_id,
          jsonb_build_object('capability', v_cap, 'to_status', v_target,
                             'task_id', v_row.task_id,
                             'idempotency_key', p_idempotency_key));

  return v_row;
end;
$$;

grant execute on function public.admin_moderate_task_media(uuid, text, text, text) to authenticated;

